Object.assign(ACT, { bonusadd(fy) { openDrawer({ title: 'Add bonus to payroll', sub: `FY ${fy}–${String(+fy + 1).slice(2)} statutory bonus as a pay item on each eligible employee’s payslip.`, saveLabel: 'Add bonus', html: form([{ n: 'month', l: 'Payroll month', req: 1, ph: 'YYYY-MM' }, { n: 'pct', l: 'Bonus rate', t: 'pct', min: 8.33, help: 'Between 8.33% and 20%.' }], { month: TODAY().slice(0, 7), pct: hrSet().bonusPct }), validate: v => !/^\d{4}-\d{2}$/.test(v.month || '') ? [{ n: 'month', m: 'Use YYYY-MM' }] : runOf(v.month) && runOf(v.month).status !== 'draft' ? [{ n: 'month', m: 'Payroll for this month is finalised. Reopen it or pick another month.' }] : (N(v.pct) < 8.33 || N(v.pct) > 20) ? [{ n: 'pct', m: 'Between 8.33% and 20%.' }] : [], onSave: async v => { ui.bonusFY = +fy; const H = { ...hrSet(), bonusPct: N(v.pct) || hrSet().bonusPct }; const months = Array.from({ length: 12 }, (_, i) => ymd(new Date(+fy, 3 + i, 1)).slice(0, 7)); const ops = []; for (const e of S.employees) { if (e.status === 'inactive' && !((hrProf(e.id).exit || {}).lastDay >= v.month + '-01')) continue; const P = hrProf(e.id); const bw = N((P.salary || {}).basic) + N((P.salary || {}).da); if (!bw || bw > H.bonusEligible) continue; let base0 = 0; for (const m of months) { const run = runOf(m); const r = run && run.rows ? run.rows.find(x => x.employeeId === e.id) : null; if (r) base0 += Math.min(N((r.earn || {}).basic) + N((r.earn || {}).da), H.bonusCeiling); else if ((!e.joinDate || e.joinDate <= m + '-28') && m <= TODAY().slice(0, 7) && e.status !== 'inactive') base0 += Math.min(bw, H.bonusCeiling); } const b = Math.round(base0 * H.bonusPct / 100); if (b > 0) ops.push({ op: 'set', path: `hradj/bonus-${fy}-${e.id}`, data: clean({ employeeId: e.id, type: 'bonus', month: v.month, amount: b, note: `Statutory bonus FY ${fy}–${String(+fy + 1).slice(2)} at ${H.bonusPct}%`, ...stampOf(byId('hradj')[`bonus-${fy}-${e.id}`]) }) }); } if (!ops.length) { toast('No eligible employees.', 'bad'); return false; } await batchAll(ops); addLog('create', 'hr', `Bonus for FY ${fy} added to ${monthLabel(v.month)} payroll`, `${ops.length} employees · ${inr(sum(ops, o => o.data.amount))}`); } }); } });

/* ---------- exits and full & final ---------- */
